import {CHAPTER_ID,CHAPTER_01} from './chapter01-data.js';
export function createChapterProgress(saved={}){const result={version:1,chapterId:CHAPTER_ID,sceneIndex:0,scenes:{}};for(const scene of CHAPTER_01.scenes){const input=saved?.chapterId===CHAPTER_ID?saved.scenes?.[scene.id]||{}:{};result.scenes[scene.id]={line:Math.max(0,Math.min(scene.dialogue.length-1,Number(input.line)||0)),seen:[...new Set((Array.isArray(input.seen)?input.seen:[]).filter(id=>scene.evidence.some(e=>e.id===id)))],choice:scene.choices.some(c=>c.id===input.choice)?input.choice:null,ending:Math.max(0,Math.min(scene.ending.length-1,Number(input.ending)||0))};}if(saved?.sceneIndex===1&&sceneReady(CHAPTER_01.scenes[0],result))result.sceneIndex=1;return result;}
export function sceneReady(scene,progress){const s=progress.scenes[scene.id];return s.line===scene.dialogue.length-1&&scene.evidence.every(e=>s.seen.includes(e.id))&&scene.choices.some(c=>c.id===s.choice&&c.correct)&&s.ending>=scene.ending.length-1;}
export function advanceChapter(progress,event){const next=structuredClone(progress),scene=CHAPTER_01.scenes[next.sceneIndex],s=next.scenes[scene.id];if(event.type==='line')s.line=Math.max(0,Math.min(scene.dialogue.length-1,s.line+event.delta));if(event.type==='inspect'&&scene.evidence.some(e=>e.id===event.id)&&!s.seen.includes(event.id))s.seen.push(event.id);if(event.type==='choice'&&s.line===scene.dialogue.length-1&&scene.evidence.every(e=>s.seen.includes(e.id))&&scene.choices.some(c=>c.id===event.id))s.choice=event.id;if(event.type==='ending'&&scene.choices.some(c=>c.id===s.choice&&c.correct))s.ending=Math.min(scene.ending.length-1,s.ending+1);if(event.type==='next'&&sceneReady(scene,next)&&next.sceneIndex===0)next.sceneIndex=1;if(event.type==='back')next.sceneIndex=Math.max(0,next.sceneIndex-1);return next;}
export function chapterStorageKey(userId){if(!userId)throw Error('AUTH_REQUIRED');return 'aiDistrict.story.'+CHAPTER_ID+'.v1.'+userId;}
export function readChapterProgress(storage,userId){const raw=storage.getItem(chapterStorageKey(userId));return createChapterProgress(raw?JSON.parse(raw):{});}
export function writeChapterProgress(storage,userId,progress){storage.setItem(chapterStorageKey(userId),JSON.stringify(progress));}
